import{_ as e,C as n,o as r,c as s,a2 as i,E as o}from"./chunks/framework.CCtxZRER.js";const b=JSON.parse('{"title":"Manajemen Stok","description":"Stock dan non-stock item, fast dan slow moving, critical stock, serta penyebab barang write off.","frontmatter":{"title":"Manajemen Stok","description":"Stock dan non-stock item, fast dan slow moving, critical stock, serta penyebab barang write off.","status":"ditinjau","dasar":"materi presentasi Gudang Teknik (slide 8–10)","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Gudang Teknik","sumber":["ppt-gudang-teknik"],"kata_kunci":["inventory","persediaan","stock item","non-stock item","fast moving","slow moving","cycle counting","critical stock","critical spare part","write off","dead stock","ROP","stok minimum","stok maksimum","FIFO","overstock"]},"headers":[],"relativePath":"divisi/manajemen-inventory.md","filePath":"divisi/manajemen-inventory.md"}'),l={name:"divisi/manajemen-inventory.md"};function m(d,a,k,u,g,c){const t=n("MermaidDiagram");return r(),s("div",null,[a[0]||(a[0]=i('<h1 id="manajemen-stok" tabindex="-1">Manajemen Stok <a class="header-anchor" href="#manajemen-stok" aria-label="Permalink to &quot;Manajemen Stok&quot;">​</a></h1><p class="lead">Tidak semua material diperlakukan sama. Ada yang harus selalu tersedia, ada yang dibeli hanya saat dibutuhkan, dan ada yang jarang dipakai tetapi tidak boleh kosong.</p><h2 id="stock-item-dan-non-stock-item" tabindex="-1">Stock item dan non-stock item <a class="header-anchor" href="#stock-item-dan-non-stock-item" aria-label="Permalink to &quot;Stock item dan non-stock item&quot;">​</a></h2>',3)),o(t,{code:"flowchart%20TD%0A%20%20accTitle%3A%20Klasifikasi%20inventory%0A%20%20accDescr%3A%20Material%20dibagi%20menjadi%20stock%20item%20dan%20non-stock%20item.%20Stock%20item%20dibagi%20lagi%20menjadi%20fast%20moving%20dan%20slow%20moving.%20Sebagian%20slow%20moving%20termasuk%20critical%20stock.%0A%20%20A%5BMaterial%5D%20--%3E%20B%5BStock%20item%3Cbr%2F%3Edipakai%20rutin%5D%0A%20%20A%20--%3E%20C%5BNon-stock%20item%3Cbr%2F%3Edipakai%20sesekali%5D%0A%20%20B%20--%3E%20D%5BFast%20moving%3Cbr%2F%3Ediminta%202%20kali%20atau%20lebih%20per%20bulan%5D%0A%20%20B%20--%3E%20E%5BSlow%20moving%3Cbr%2F%3Ediminta%201%20kali%20per%20bulan%5D%0A%20%20E%20--%3E%20F%5BCritical%20stock%3Cbr%2F%3Eminimal%201%20unit%20harus%20tersedia%5D%0A%20%20C%20--%3E%20G%5BDibeli%20saat%20user%20membutuhkan%5D%0A"}),a[1]||(a[1]=i('<h3 id="stock-item" tabindex="-1">Stock item <a class="header-anchor" href="#stock-item" aria-label="Permalink to &quot;Stock item&quot;">​</a></h3><p>Material yang <strong>sering dibutuhkan</strong> user. Pemakaiannya diamati dalam periode tertentu, lalu dikelompokkan menjadi <em>fast moving</em> atau <em>slow moving</em>. Karena rutin dipakai, stoknya harus dijaga sesuai intensitas pemakaian. Untuk itu dihitung tiga angka:</p><ul><li><strong>Stok maksimum</strong>: batas atas agar tidak menumpuk.</li><li><strong>Stok minimum</strong>: batas bawah agar tidak kehabisan.</li><li><strong>ROP</strong> (<em>Reorder Point</em>): titik saat material harus dipesan kembali.</li></ul><p>Cara menghitungnya dijelaskan di tutorial <a href="/WareHouse/tutorial/min-max-rop">Menghitung Min, Maks &amp; ROP</a>.</p><h3 id="non-stock-item" tabindex="-1">Non-stock item <a class="header-anchor" href="#non-stock-item" aria-label="Permalink to &quot;Non-stock item&quot;">​</a></h3><p>Material yang kebutuhannya <strong>hanya sesekali</strong> dan tidak rutin. Material ini tidak perlu disimpan sebagai stok dan baru dibeli ketika user membutuhkannya.</p><h2 id="fast-moving-dan-slow-moving" tabindex="-1">Fast moving dan slow moving <a class="header-anchor" href="#fast-moving-dan-slow-moving" aria-label="Permalink to &quot;Fast moving dan slow moving&quot;">​</a></h2><p>Di gudang yang berada di dalam pabrik (<em>manufacturing plant warehouse</em>), kecepatan perputaran tiap material berbeda. Penentuannya menggunakan metode <strong>cycle counting</strong>:</p><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Kategori</th><th>Ciri</th><th>Kriteria</th></tr></thead><tbody><tr><td data-label="Kategori"><strong>Fast moving</strong></td><td data-label="Ciri">Sering dipakai, perputarannya cepat</td><td data-label="Kriteria">Diminta atau direservasi <strong>2 kali atau lebih</strong> dalam sebulan</td></tr><tr><td data-label="Kategori"><strong>Slow moving</strong></td><td data-label="Ciri">Jarang dipakai, perputarannya lambat</td><td data-label="Kriteria">Diminta atau direservasi <strong>1 kali</strong> dalam sebulan</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Belum tercakup</p><p>Materi presentasi belum menjelaskan kategori untuk material yang tidak diminta sama sekali dalam sebulan. Tanyakan ke pembimbing apakah material seperti itu dihitung slow moving, atau diperiksa sebagai calon write off.</p></div><p>Latihan mengklasifikasikan material ada di tutorial <a href="/WareHouse/tutorial/fast-slow-moving">Menentukan Fast &amp; Slow Moving</a>.</p><h2 id="critical-spare-part" tabindex="-1">Critical spare part <a class="header-anchor" href="#critical-spare-part" aria-label="Permalink to &quot;Critical spare part&quot;">​</a></h2><h3 id="critical-stock" tabindex="-1">Critical stock <a class="header-anchor" href="#critical-stock" aria-label="Permalink to &quot;Critical stock&quot;">​</a></h3><p>Material yang termasuk <em>slow moving</em>, tetapi <strong>harus ada</strong> jika sewaktu-waktu dibutuhkan user. Stok minimumnya <strong>1 unit</strong> untuk menutup permintaan mendadak. Contoh umumnya adalah suku cadang mesin yang jarang rusak, tetapi jika rusak dan tidak tersedia, mesin akan berhenti lama.</p><h3 id="write-off" tabindex="-1">Write off <a class="header-anchor" href="#write-off" aria-label="Permalink to &quot;Write off&quot;">​</a></h3><p>Persediaan yang <strong>sudah tidak dipakai lagi</strong>. Penyebabnya antara lain:</p><ol><li><strong>Kesalahan prediksi</strong><ul><li>Umur pakai produk lebih pendek dari rencana.</li><li>Pemakaian user tidak sebanyak yang direncanakan.</li><li>Pengendalian stok kurang baik, misalnya menurut data stok habis tetapi barangnya ternyata masih ada.</li><li>Saat memesan barang, posisi stok sebenarnya tidak diperhatikan.</li><li>Mesin sudah tidak dipakai atau sudah dimodifikasi, sehingga suku cadangnya tidak terpakai.</li><li>Barang yang dipesan salah atau tidak sesuai spesifikasi.</li></ul></li><li><strong>Barang kedaluwarsa</strong><ul><li><em>Overstock</em>: terlalu lama disimpan sehingga mutunya turun.</li><li>Sistem FIFO belum diterapkan dengan benar.</li></ul></li></ol><p>Cara umum menangani barang write off dibahas di <a href="/WareHouse/sop/dead-stock">SOP Write Off &amp; Barang Rusak</a>.</p>',18))])}const h=e(l,[["render",m]]);export{b as __pageData,h as default};
